from pathlib import Path

layout=Path('app/src/main/res/layout')
def text(id, string, size='bodyM', margin=12, color='textPrimary'):
    return f'<TextView android:id="@+id/{id}" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="@dimen/spacing_{"md" if margin==12 else "xxl"}" android:text="@string/{string}" android:textSize="@dimen/text_{size}" android:fontFamily="@font/sora_{"semibold" if size.startswith("title") else "regular"}" android:textColor="@color/{color}"/>'
def button(id,string,outline=False):
    return f'<TextView android:id="@+id/{id}" android:layout_width="match_parent" android:layout_height="50dp" android:layout_marginTop="@dimen/spacing_md" android:gravity="center" android:fontFamily="@font/sora_bold" android:textSize="@dimen/text_buttonL" android:textColor="@color/{"primarySoft" if outline else "textPrimary"}" android:background="@drawable/{"bg_outline_button" if outline else "bg_cta_gradient"}" android:text="@string/{string}" android:clickable="true" android:focusable="true"/>'
def header(string):
    return f'''<LinearLayout android:layout_width="match_parent" android:layout_height="56dp" android:gravity="center_vertical" android:orientation="horizontal"><ImageButton android:id="@+id/btnBack" android:layout_width="44dp" android:layout_height="44dp" android:padding="12dp" android:background="@drawable/bg_header_circle_dark" android:src="@drawable/ic_pin_back" android:contentDescription="@string/back"/>
<TextView android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:layout_marginStart="12dp" android:fontFamily="@font/sora_semibold" android:textSize="@dimen/text_titleL" android:textColor="@color/textPrimary" android:text="@string/{string}"/></LinearLayout>'''
def screen(name,title,content,actions=''):
    layout.joinpath(name+'.xml').write_text(f'''<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" xmlns:app="http://schemas.android.com/apk/res-auto" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="@color/bg" android:paddingHorizontal="16dp" android:paddingBottom="16dp">{header(title)}
<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:fillViewport="true"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingBottom="24dp">{content}</LinearLayout></androidx.core.widget.NestedScrollView>{actions}</LinearLayout>''',encoding='utf-8')
def card(content):
    return f'<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="24dp" android:orientation="vertical" android:padding="16dp" android:background="@drawable/bg_card_dark">{content}</LinearLayout>'
screen('fragment_voice_guide','setup_guide_title',text('tvHeading','setup_guide_heading','titleS',24)+card(text('tvVoice','setup_guide_voice','titleS')+text('tvVoiceBody','setup_guide_voice_body',color='textSecondary'))+card(text('tvQuestion','setup_guide_question','titleS')+text('tvQuestionBody','setup_guide_question_body',color='textSecondary'))+text('tvPermissions','setup_guide_permissions','titleS',24)+card(text('tvPermissionBody','setup_guide_permissions_body',color='textSecondary')),button('btnStart','start_voice_setup'))
screen('fragment_setup_complete','setup_done_title',text('tvBody','setup_done_body',color='textSecondary')+card(text('tvTip','setup_backup_tip','bodyS',color='textSecondary'))+button('btnPin','pin_lock_title',True)+button('btnPattern','pattern_lock_title',True)+button('btnFingerprint','fingerprint_title',True)+card(text('tvPreview','preview','titleS')+button('btnPreview','take_a_look'))+card(text('tvThemes','lock_screen_themes','titleS')+button('btnThemes','see_all')),button('btnHome','home'))
screen('fragment_voice_setup','voice_step_title','''<LinearLayout android:layout_width="match_parent" android:layout_height="40dp" android:layout_marginTop="24dp" android:orientation="horizontal" android:gravity="center"><View android:layout_width="20dp" android:layout_height="20dp" android:background="@drawable/bg_voice_step_active"/><View android:layout_width="48dp" android:layout_height="2dp" android:background="@color/primaryLight"/><View android:layout_width="16dp" android:layout_height="16dp" android:background="@drawable/bg_voice_step_inactive"/></LinearLayout>'''+text('tvTitle','voice_record_title','titleS',24)+text('tvSubtitle','voice_record_description','bodyS',color='textSecondary')+card(text('tvRecorded','record_voice','caption',color='primarySoft')+text('tvTimer','timer_zero','titleL')+text('tvPhrase','voice_phrase_placeholder','bodyL')+'''<TextView android:id="@+id/btnLanguage" android:layout_width="wrap_content" android:layout_height="44dp" android:layout_marginTop="24dp" android:paddingHorizontal="24dp" android:gravity="center" android:fontFamily="@font/sora_semibold" android:textSize="@dimen/text_buttonS" android:textColor="@color/primarySoft" android:background="@drawable/bg_pill_outline" android:text="English"/>
<ImageButton android:id="@+id/btnRecord" android:layout_width="57dp" android:layout_height="57dp" android:layout_gravity="center_horizontal" android:layout_marginTop="24dp" android:padding="16dp" android:src="@drawable/ic_preview_mic_white" android:background="@drawable/bg_cta_gradient" android:contentDescription="@string/record_voice"/>'''+text('tvTapHint','tap_to_record','titleS')+text('tvLimit','voice_time_limit','caption',24,'textSecondary')),button('btnRecordAgain','record_again',True)+button('btnContinue','continue_text'))
screen('fragment_note_record','note_new_title','''<TextView android:id="@+id/btnLanguage" android:layout_width="wrap_content" android:layout_height="44dp" android:paddingHorizontal="24dp" android:gravity="center" android:text="English" android:textColor="@color/primarySoft" android:textSize="@dimen/text_buttonS" android:background="@drawable/bg_pill_outline"/>'''+text('tvHint','note_language_hint','bodyS',color='textSecondary')+card(text('tvTranscript','voice_phrase_placeholder','bodyL')+text('tvTimer','timer_zero','titleL')),button('btnStart','start'))
screen('fragment_note_detail','note_detail_title',text('tvTitle','note_detail_title','titleL')+text('tvMetadata','timer_zero','caption',color='textSecondary')+card(text('tvTranscriptHeading','note_transcript','titleS')+text('tvTranscript','voice_phrase_placeholder','bodyL'))+card(text('tvSummaryHeading','note_summary','titleS')+text('tvSummary','voice_phrase_placeholder','bodyM')),button('btnCopy','note_copy',True)+button('btnShare','share'))
screen('fragment_security_question','security_step_title',text('tvTitle','security_pick_title','titleS',24)+text('tvSubtitle','security_pick_body','bodyS',color='textSecondary')+'''<androidx.recyclerview.widget.RecyclerView android:id="@+id/rvQuestions" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="24dp" android:nestedScrollingEnabled="false"/>
<LinearLayout android:id="@+id/answerCard" android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:visibility="gone">'''+button('btnAnother','pick_another_question',True)+text('tvQuestion','security_pick_title','bodyL',24)+'''<EditText android:id="@+id/etAnswer" android:layout_width="match_parent" android:layout_height="wrap_content" android:minHeight="58dp" android:layout_marginTop="12dp" android:background="@drawable/bg_answer_field" android:padding="16dp" android:fontFamily="@font/sora_medium" android:textSize="@dimen/text_bodyL" android:textColor="@color/textPrimary" android:textColorHint="@color/textPlaceholder" android:hint="@string/enter_your_answer" android:inputType="textCapSentences" android:maxLength="100"/>'''+text('tvError','security_answer_short','caption',color='errorSoft')+'</LinearLayout>',button('btnSave','continue_text'))
print('Created setup, recovery question, completion, and note flow layouts.')
